import React, { useEffect, useState } from "react";
import { api, fmt } from "../lib/api";
import { useAuth } from "../context/AuthContext";
import { toast } from "sonner";

const C = {
  cream: "#f5f2ec",
  darkGreen: "#0a3026",
  rust: "#c25942",
  muted: "#666",
  border: "rgba(0,0,0,0.09)",
  green100: "#e8f0ec",
};
const serif = "'Playfair Display', serif";
const body  = "'EB Garamond', Georgia, serif";

const PROFILE_PICS = [
  "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcRVhlIIiKC3ow_uxswneWfAjSk5Zutw-TLTBw&s",
  "https://i.pinimg.com/736x/ec/f8/ce/ecf8ce936874540a65ea1e1e4ccaf26d.jpg",
  "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcR9VeKAzzSm-KHRQ48PjwEhEozg4otym_Hu2A&s",
  "https://www.belmont.edu/profiles/mary-claire-dismukes/_images/mary-claire-dismukes.webp",
  "https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcSj5-CC8IqhXvWgD1OYsCfT4IChGKsrBA7xvw&s",
];

const STATUS_STYLE = {
  pending:  { bg: "#fdf3e7", color: "#b45309", label: "Pending" },
  accepted: { bg: "#e8f5ee", color: "#166534", label: "Accepted" },
  rejected: { bg: "#fdecea", color: "#991b1b", label: "Declined" },
};

const Avatar = ({ name, index }) => (
  <div style={{ position: "relative", flexShrink: 0 }}>
    <img
      src={PROFILE_PICS[index % PROFILE_PICS.length]}
      alt={name}
      style={{
        width: 54, height: 54, borderRadius: "50%",
        objectFit: "cover", display: "block",
        border: `2px solid ${C.border}`,
      }}
      onError={e => { e.target.style.display = "none"; e.target.nextSibling.style.display = "flex"; }}
    />
    <div style={{
      display: "none", width: 54, height: 54, borderRadius: "50%",
      background: C.darkGreen, color: "#fff",
      alignItems: "center", justifyContent: "center",
      fontFamily: serif, fontSize: "1.3rem",
    }}>{name?.[0]}</div>
  </div>
);

const EmptyState = ({ tab }) => (
  <div style={{
    textAlign: "center", padding: "5rem 2rem",
    border: `1px solid ${C.border}`, background: "#fff",
  }}>
    {/* Simple decorative circle */}
    <div style={{
      width: 80, height: 80, borderRadius: "50%",
      background: C.green100, border: `2px dashed ${C.border}`,
      display: "flex", alignItems: "center", justifyContent: "center",
      margin: "0 auto 1.5rem",
      color: C.darkGreen,
    }}>
      <svg width="32" height="32" viewBox="0 0 24 24" fill="none"
        stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round">
        <path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"/>
        <circle cx="9" cy="7" r="4"/>
        <path d="M23 21v-2a4 4 0 0 0-3-3.87M16 3.13a4 4 0 0 1 0 7.75"/>
      </svg>
    </div>
    <div style={{ fontFamily: serif, fontSize: "1.4rem", color: C.darkGreen, marginBottom: "0.5rem" }}>
      {tab === "in" ? "No incoming requests yet." : "You haven't sent any requests yet."}
    </div>
    <p style={{ color: C.muted, fontSize: "0.92rem", maxWidth: 380, margin: "0 auto 1.5rem" }}>
      {tab === "in"
        ? "When students request your mentorship, they'll appear here."
        : "Visit the directory to find an alumni mentor and send your first request."}
    </p>
    {tab === "out" && (
      <a href="/directory?role=alumni" style={{
        display: "inline-block",
        background: C.darkGreen, color: "#fff",
        padding: "0.75rem 1.8rem", fontSize: "0.9rem",
        fontFamily: body, textDecoration: "none",
        letterSpacing: "0.03em",
      }}>
        Browse Alumni →
      </a>
    )}
  </div>
);

export default function Mentorship() {
  const { user } = useAuth();
  const [list, setList] = useState([]);
  const [tab, setTab] = useState(user?.role === "alumni" ? "in" : "out");

  const load = async () => {
    try { const { data } = await api.get("/mentorship/my"); setList(data); }
    catch (_) {}
  };

  useEffect(() => { load(); }, []);

  const act = async (id, status) => {
    try { await api.patch(`/mentorship/${id}`, { status }); toast.success(status); load(); }
    catch (e) { toast.error(fmt(e.response?.data?.detail)); }
  };

  const incoming = list.filter(r => r.alumniId === user?.id);
  const outgoing  = list.filter(r => r.studentId === user?.id);
  const rows = tab === "in" ? incoming : outgoing;

  const accepted = list.filter(r => r.status === "accepted").length;
  const pending  = list.filter(r => r.status === "pending").length;

  return (
    <div style={{ background: C.cream, minHeight: "100vh", fontFamily: body }}>
      <div style={{ maxWidth: 960, margin: "0 auto", padding: "3.5rem 2.5rem" }}>

        {/* ── HEADER ── */}
        <div style={{ marginBottom: "2.5rem" }}>
          <div style={{
            fontSize: "0.62rem", letterSpacing: "0.22em", textTransform: "uppercase",
            color: C.rust, fontWeight: 700, marginBottom: "0.7rem",
            borderTop: `1px solid ${C.rust}`, paddingTop: "0.4rem", display: "inline-block",
          }}>Mentorship</div>
          <h1 style={{
            fontFamily: serif, fontSize: "clamp(2rem, 3.5vw, 3rem)",
            color: C.darkGreen, fontWeight: 400, margin: 0,
          }}>Requests & Responses</h1>
          <p style={{ color: C.muted, marginTop: "0.5rem", fontSize: "0.95rem" }}>
            Manage your mentorship connections in one place.
          </p>
        </div>

        {/* ── STATS STRIP ── */}
        <div style={{
          display: "grid", gridTemplateColumns: "repeat(3, 1fr)",
          gap: "1px", background: C.border, border: `1px solid ${C.border}`,
          marginBottom: "2.5rem",
        }}>
          {[
            { label: "Total",    value: list.length },
            { label: "Active",   value: accepted },
            { label: "Pending",  value: pending },
          ].map(s => (
            <div key={s.label} style={{
              background: C.cream, padding: "1.4rem 1.8rem",
              display: "flex", alignItems: "center", gap: "1rem",
            }}>
              <div style={{ fontFamily: serif, fontSize: "2.2rem", color: C.darkGreen, lineHeight: 1 }}>
                {s.value}
              </div>
              <div style={{
                fontSize: "0.62rem", letterSpacing: "0.18em",
                textTransform: "uppercase", color: C.rust, fontWeight: 700,
              }}>{s.label}</div>
            </div>
          ))}
        </div>

        {/* ── TABS ── */}
        <div style={{
          display: "flex", borderBottom: `1px solid ${C.border}`,
          marginBottom: "1.8rem",
        }}>
          {[
            { key: "in",  label: `Incoming (${incoming.length})` },
            { key: "out", label: `Outgoing (${outgoing.length})` },
          ].map(t => (
            <button
              key={t.key}
              onClick={() => setTab(t.key)}
              style={{
                background: "none", border: "none", cursor: "pointer",
                padding: "0.8rem 1.4rem", fontFamily: body, fontSize: "1rem",
                color: tab === t.key ? C.darkGreen : C.muted,
                borderBottom: tab === t.key ? `2px solid ${C.darkGreen}` : "2px solid transparent",
                marginBottom: "-1px", letterSpacing: "0.02em",
                transition: "color 0.15s",
              }}
            >
              {t.label}
            </button>
          ))}
        </div>

        {/* ── REQUEST CARDS ── */}
        {rows.length === 0
          ? <EmptyState tab={tab} />
          : (
            <div style={{ display: "flex", flexDirection: "column", gap: "1px", background: C.border, border: `1px solid ${C.border}` }}>
              {rows.map((r, i) => {
                const personName = tab === "in" ? r.studentName : r.alumniName;
                const personLabel = tab === "in" ? "From" : "To";
                const st = STATUS_STYLE[r.status] ?? STATUS_STYLE.pending;

                return (
                  <div key={r._id} style={{
                    background: "#fff", padding: "1.8rem 2rem",
                    display: "flex", gap: "1.4rem", alignItems: "flex-start",
                  }}>
                    {/* Avatar */}
                    <Avatar name={personName} index={i} />

                    {/* Body */}
                    <div style={{ flex: 1 }}>
                      <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", marginBottom: "0.3rem" }}>
                        <div>
                          <div style={{
                            fontSize: "0.6rem", letterSpacing: "0.18em",
                            textTransform: "uppercase", color: C.rust,
                            fontWeight: 700, marginBottom: "0.3rem",
                          }}>{personLabel}</div>
                          <div style={{
                            fontFamily: serif, fontSize: "1.15rem", color: C.darkGreen,
                          }}>{personName}</div>
                        </div>

                        {/* Status badge */}
                        <span style={{
                          background: st.bg, color: st.color,
                          fontSize: "0.7rem", letterSpacing: "0.1em",
                          textTransform: "uppercase", fontWeight: 700,
                          padding: "0.3rem 0.75rem", borderRadius: 2,
                        }}>{st.label}</span>
                      </div>

                      {/* Message */}
                      {r.message && (
                        <p style={{
                          color: C.muted, fontSize: "0.92rem",
                          lineHeight: 1.65, marginTop: "0.6rem",
                          marginBottom: "0", maxWidth: 580,
                          borderLeft: `3px solid ${C.border}`,
                          paddingLeft: "0.9rem",
                        }}>
                          "{r.message}"
                        </p>
                      )}

                      {/* Actions for incoming pending */}
                      {tab === "in" && r.status === "pending" && (
                        <div style={{ display: "flex", gap: "0.6rem", marginTop: "1.2rem" }}>
                          <button
                            onClick={() => act(r._id, "accepted")}
                            style={{
                              background: C.darkGreen, color: "#fff", border: "none",
                              padding: "0.6rem 1.4rem", fontSize: "0.88rem",
                              fontFamily: body, cursor: "pointer", letterSpacing: "0.03em",
                            }}
                          >
                            Accept
                          </button>
                          <button
                            onClick={() => act(r._id, "rejected")}
                            style={{
                              background: "transparent", color: C.muted,
                              border: `1px solid ${C.border}`,
                              padding: "0.6rem 1.4rem", fontSize: "0.88rem",
                              fontFamily: body, cursor: "pointer", letterSpacing: "0.03em",
                            }}
                          >
                            Decline
                          </button>
                        </div>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          )}
      </div>
    </div>
  );
}
